function PatientRegister(){const [index,setIndex]=useState<Row|null>(null),[selected,setSelected]=useState(""),[detail,setDetail]=useState<Row|null>(null),[error,setError]=useState("");useEffect(()=>{let alive=true;const load=()=>api<Row>("/api/admin/patient-register").then(x=>{if(!alive)return;setIndex(x);if(selected&&!x.patients.some((p:Row)=>p.id===selected)){setSelected("");setDetail(null)}}).catch((e:any)=>alive&&setError(e.message));load();const timer=setInterval(load,3000);return()=>{alive=false;clearInterval(timer)}},[selected]);useEffect(()=>{let alive=true;if(!selected){setDetail(null);return()=>{alive=false}}api<Row>("/api/admin/patient-register/"+selected).then(x=>alive&&setDetail(x)).catch((e:any)=>{if(alive){setDetail(null);setError(e.message)}});return()=>{alive=false}},[selected]);const labels:Record<string,string>={profile:"Profile",appointments:"Appointments",consent_records:"Privacy choices",clinical_notes:"Clinical notes",prescriptions:"Prescriptions",rights_requests:"Data requests",complaints:"Complaints",erasure_actions:"Erasure actions",audit_events:"Patient activity"};return <div className="page-stack"><Intro icon={<Database/>} title="Patient register" body="Live patient count and linked records from the local database. Visible only to the signed-in security admin."/>{error&&<div className="alert error"><ShieldAlert size={18}/><span>{error}</span><button onClick={()=>setError("")}>Dismiss</button></div>}<Card><div className="section-head"><div><span className="eyebrow">LIVE DATABASE VIEW</span><h3>{index?.active_patient_count??"â€¦"} active patient{index?.active_patient_count===1?"":"s"}</h3></div><Pill tone="mint">Refreshes every 3 seconds</Pill></div><div className="info-strip"><Shield size={16}/><span>Only active patient accounts are counted. Inactive erased profiles can remain as minimal tombstones; backups and external systems are not shown.</span></div><p className="micro-note">Last refreshed: {index?.refreshed_at?when(index.refreshed_at):"Loading"} Â· Inactive erased profiles: {index?.inactive_erased_profiles??"â€¦"}</p>{!index?.patients?.length?<Empty title="No active patients" body="The live database currently has zero active patient profiles."/>:<div className="patient-tabs" style={{marginTop:14}}>{index.patients.map((p:Row)=><button key={p.id} className={selected===p.id?"active":""} onClick={()=>setSelected(p.id)}><span className="avatar small">{initials(p.display_name)}</span><span><b>{p.display_name}</b><small>{p.masked_contact||"No contact"} Â· {Object.values(p.records).reduce((n:any,x:any)=>n+x,0)} linked records</small></span></button>)}</div>}{selected&&detail&&<div className="patient-record-area"><div className="section-head"><div><span className="eyebrow">SELECTED PATIENT Â· ALL APP DATA</span><h3>{detail.profile.display_name}</h3></div><Pill tone="amber">Sensitive view audited</Pill></div><p className="micro-note">Passwords, password hashes, session tokens, and database secrets are intentionally excluded. The encrypted database is decrypted only for this authenticated admin view.</p>{Object.entries(detail).filter(([key])=>key!=="excluded").map(([key,value])=><details className="patient-data-section" key={key} open><summary>{labels[key]??key.replaceAll("_"," ")} <span>{Array.isArray(value)?value.length:value&&typeof value==="object"?Object.keys(value).length:""}</span></summary><pre>{JSON.stringify(value,null,2)}</pre></details>)}</div>}</Card><p className="micro-note">{index?.note}</p></div>}function Incidents({refresh,act}:{refresh:number,act:(p:string,m:string,b?:any)=>Promise<boolean>}){const {data,loading}=useData<Row[]>("/api/admin/incidents",refresh);const [summary,setSummary]=useState(""),[selected,setSelected]=useState<string|null>(null),[note,setNote]=useState(""),[action,setAction]=useState("containment"),[status,setStatus]=useState("containing");async function create(e:FormEvent){e.preventDefault();if(await act("/api/admin/incidents","POST",{summary,severity:"medium",source:"administrator report",affected_categories:["appointments"]}))setSummary("")}const active=(data??[]).find(i=>i.id===selected);return <div className="page-stack"><Intro icon={<ShieldAlert/>} title="Security incidents" body="Record a signal, investigate, and track response. An alert is not proof of a breach."/><button className="button secondary" onClick={()=>act("/api/admin/incidents/demo-simulate","POST")}><Sparkles size={16}/> Simulate synthetic incident</button><Card><div className="section-head"><div><span className="eyebrow">NEW INCIDENT</span><h3>Open a review</h3></div><Pill tone="amber">No real data exposed</Pill></div><form className="form-grid" onSubmit={create}><Field label="Short summary"><input required minLength={5} maxLength={1200} value={summary} onChange={e=>setSummary(e.target.value)} placeholder="Describe a signal to investigate."/></Field><Button>Create incident <Plus size={16}/></Button></form></Card><Card><div className="section-head"><div><span className="eyebrow">INCIDENT REGISTER</span><h3>{(data??[]).length} incidents</h3></div><Pill>Restricted view</Pill></div>{loading?<div className="skeleton"/>:!data?.length?<Empty title="No incident activity" body="Open a review or simulate a synthetic incident."/>:<div className="row-list">{data.map(i=><button key={i.id} className="quick-item incident-item" onClick={()=>setSelected(selected===i.id?null:i.id)}><span className="quick-icon q3"><ShieldAlert size={17}/></span><span><b>{i.summary}</b><small>{when(i.detected_at)} Â· {i.severity} Â· {i.actions?.length??0} actions</small></span><Pill tone={i.status==="closed"?"mint":"amber"}>{i.status.replaceAll("_"," ")}</Pill><ChevronRight size={16}/></button>)}</div>}{active&&<div className="incident-detail"><div className="section-head"><div><span className="eyebrow">ACTION TIMELINE</span><h3>Incident {active.id.slice(0,8).toUpperCase()}</h3></div><Pill>{active.status}</Pill></div><div className="timeline">{active.actions?.map((a:Row)=><div className="timeline-item" key={a.id}><span/><div><b>{a.action.replaceAll("_"," ")}</b><small>{when(a.occurred_at)}</small><p>{a.note}</p></div></div>)}</div><form className="review-grid" onSubmit={async e=>{e.preventDefault();if(await act("/api/admin/incidents/"+active.id+"/actions","POST",{action,note,status}))setNote("")}}><Field label="Next action"><select value={action} onChange={e=>setAction(e.target.value)}>{["containment","investigation","impact_assessment","notification_review","recovery","closure","false_positive","duplicate"].map(x=><option value={x} key={x}>{x.replaceAll("_"," ")}</option>)}</select></Field><Field label="Action note"><textarea required minLength={3} rows={2} value={note} onChange={e=>setNote(e.target.value)}/></Field><Field label="Incident status"><select value={status} onChange={e=>setStatus(e.target.value)}>{["triage","containing","investigating","notification_review","recovering","closed","false_positive","duplicate"].map(x=><option key={x} value={x}>{x.replaceAll("_"," ")}</option>)}</select></Field><Button>Record action <Check size={15}/></Button></form></div>}</Card></div>}
function Audit({refresh}:{refresh:number}){const {data,loading}=useData<Row[]>("/api/admin/audit-events?limit=100",refresh);return <div className="page-stack"><Intro icon={<ClipboardCheck/>} title="Audit trail" body="Recent administrative and patient actions. The demo minimizes details and does not claim absolute immutability."/><Card><div className="section-head"><div><span className="eyebrow">RECENT ACTIVITY</span><h3>Latest events</h3></div><Pill>Security admin only</Pill></div>{loading?<div className="skeleton"/>:!data?.length?<Empty title="No audit events yet" body="Actions will be recorded here as the demo is used."/>:<div className="table-wrap"><table><thead><tr><th>Action</th><th>Actor</th><th>Record</th><th>Time</th><th>Outcome</th></tr></thead><tbody>{data.map(a=><tr key={a.id}><td><b>{a.action.replaceAll("."," / ")}</b>{a.reason&&<small>{a.reason}</small>}</td><td>{a.actor_id?.slice(0,8)??"System"}</td><td>{a.entity_type}</td><td>{when(a.occurred_at)}</td><td><Pill tone={a.outcome==="success"?"mint":"amber"}>{a.outcome}</Pill></td></tr>)}</tbody></table></div>}</Card></div>}
function Retention({refresh}:{refresh:number}){const {data,loading}=useData<Row[]>("/api/admin/retention-policies",refresh);return <div className="page-stack"><Intro icon={<ClipboardList/>} title="Retention review" body="Demo categories are intentionally unverified. Confirm obligations before setting real retention periods."/><div className="alert warning"><ShieldAlert size={18}/><span>These placeholders are not legal advice or fixed statutory periods.</span></div><Card><div className="section-head"><div><span className="eyebrow">POLICY REGISTER</span><h3>{(data??[]).length} categories</h3></div><Pill tone="amber">Needs legal review</Pill></div>{loading?<div className="skeleton"/>:!data?.length?<Empty title="Run the demo seed" body="Retention placeholders are loaded by the seed command."/>:<div className="row-list">{data.map(p=><div className="retention-row" key={p.id}><div className="row-icon violet"><ClipboardList size={17}/></div><div className="row-main"><b>{p.data_category.replaceAll("_"," ")}</b><small>{p.rule_description}</small><small>Trigger: {p.retention_trigger}{p.legal_reference?" Â· "+p.legal_reference:""}</small></div><Pill tone={p.verified?"mint":"amber"}>{p.verified?"Verified":"Review required"}</Pill></div>)}</div>}</Card></div>}

